// ReBuild: original educational sketch for Arduino UNO R3.
// Concept and wiring reference: Arduino BlinkWithoutDelay.
unsigned long previous=0;
bool lit=false;
void setup(){ pinMode(LED_BUILTIN,OUTPUT); }
void loop(){ unsigned long now=millis(); if(now-previous>=1000){ previous=now; lit=!lit; digitalWrite(LED_BUILTIN,lit); } }

// ReBuild: original educational sketch for Arduino UNO R3.
// Concept and wiring reference: Arduino Debounce.
bool lastRaw=LOW, stable=LOW, lit=false;
unsigned long changed=0;
void setup(){ pinMode(2,INPUT); pinMode(LED_BUILTIN,OUTPUT); }
void loop(){ bool raw=digitalRead(2); if(raw!=lastRaw)changed=millis();
 if(millis()-changed>=50 && raw!=stable){ stable=raw; if(stable){ lit=!lit; digitalWrite(LED_BUILTIN,lit); } } lastRaw=raw; }

// ReBuild: original educational sketch for Arduino UNO R3.
// Concept and wiring reference: Arduino StateChangeDetection.
bool previous=LOW;
unsigned long count=0;
void setup(){ pinMode(2,INPUT); Serial.begin(9600); }
void loop(){ bool current=digitalRead(2); if(current && !previous){ count++; Serial.println(count); } previous=current; delay(50); }

