// ReBuild: original educational sketch for Arduino UNO R3.
// Concept and wiring reference: Arduino Smoothing.
int values[10]={0}; int index=0; long sum=0; int count=0;
void setup(){ Serial.begin(9600); }
void loop(){ sum-=values[index]; values[index]=analogRead(A0); sum+=values[index]; index=(index+1)%10; if(count<10)count++; Serial.println(sum/count); delay(20); }

// ReBuild: original educational sketch for Arduino UNO R3.
// Concept and wiring reference: Arduino Calibration.
int lowValue=1023,highValue=0;
void setup(){ pinMode(9,OUTPUT); Serial.begin(9600); unsigned long start=millis();
 while(millis()-start<5000){int v=analogRead(A0); lowValue=min(lowValue,v); highValue=max(highValue,v);} }
void loop(){ if(highValue<=lowValue){analogWrite(9,0); Serial.println("Reset and vary light during calibration"); delay(500); return;}
 int v=constrain(analogRead(A0),lowValue,highValue); int duty=map(v,lowValue,highValue,0,255); analogWrite(9,duty); Serial.println(duty); delay(20); }

